dashboard.definition:
{
  "title": "Background Radiation",
  "description": "Home Geiger readings compared with public government radiation networks",
  "inputs": {
    "input_global_trp": {
      "options": {
        "defaultValue": "-24h@h,now",
        "token": "global_time"
      },
      "title": "Global Time Range",
      "type": "input.timerange"
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      },
      "ds.spl2": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "visualizations": {
    "viz_home_md": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "### Home sensor\nLocal monitor from `index=radsensor` (`cpm` and `usvh`). Government feeds are stored as `sourcetype=gov:radiation:json` and excluded here."
      }
    },
    "viz_home_line": {
      "dataSources": {
        "primary": "ds_home_line"
      },
      "options": {
        "dataValuesDisplay": "minmax",
        "nullValueDisplay": "connect"
      },
      "title": "Home CPM and uSv/h",
      "type": "splunk.line"
    },
    "viz_home_cpm": {
      "dataSources": {
        "primary": "ds_home_cpm"
      },
      "options": {
        "numberPrecision": 1
      },
      "title": "Home CPM",
      "type": "splunk.singlevalue"
    },
    "viz_home_usvh": {
      "dataSources": {
        "primary": "ds_home_usvh"
      },
      "options": {
        "numberPrecision": 4
      },
      "title": "Home uSv/h",
      "type": "splunk.singlevalue"
    },
    "viz_home_latest_cpm": {
      "dataSources": {
        "primary": "ds_home_latest_cpm"
      },
      "options": {
        "numberPrecision": 1
      },
      "title": "Latest CPM",
      "type": "splunk.singlevalue"
    },
    "viz_home_latest_usvh": {
      "dataSources": {
        "primary": "ds_home_latest_usvh"
      },
      "options": {
        "numberPrecision": 4
      },
      "title": "Latest uSv/h",
      "type": "splunk.singlevalue"
    },
    "viz_world_md": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "### Live world vs home\nLatest reading per station from public government networks, grouped by country: **Germany** BfS, **Finland** STUK, **Austria** SFWS, **Switzerland** NADAM (daily mean), **Japan** NRA, **Australia** ARPANSA, **United States** EPA RadNet (hourly), **Canada** Health Canada FPS (terrestrial only, so it reads lower). Countries without a live feed show their published typical value."
      }
    },
    "viz_world_home": {
      "dataSources": {
        "primary": "ds_home_latest_usvh"
      },
      "options": {
        "numberPrecision": 4
      },
      "title": "Home latest uSv/h",
      "type": "splunk.singlevalue"
    },
    "viz_world_median": {
      "dataSources": {
        "primary": "ds_world_median"
      },
      "options": {
        "numberPrecision": 4
      },
      "title": "Live world median uSv/h (median of countries)",
      "type": "splunk.singlevalue"
    },
    "viz_world_delta": {
      "dataSources": {
        "primary": "ds_home_vs_world"
      },
      "options": {
        "numberPrecision": 4
      },
      "title": "Home minus world median",
      "type": "splunk.singlevalue"
    },
    "viz_world_ratio": {
      "dataSources": {
        "primary": "ds_home_vs_world_ratio"
      },
      "options": {
        "numberPrecision": 2
      },
      "title": "Home / world median",
      "type": "splunk.singlevalue"
    },
    "viz_world_bar": {
      "dataSources": {
        "primary": "ds_compare_bar"
      },
      "options": {},
      "title": "Home vs live country medians (uSv/h)",
      "type": "splunk.column"
    },
    "viz_world_line": {
      "dataSources": {
        "primary": "ds_compare_time"
      },
      "options": {
        "nullValueDisplay": "connect"
      },
      "title": "Home vs country medians over time",
      "type": "splunk.line"
    },
    "viz_world_table": {
      "dataSources": {
        "primary": "ds_network_table"
      },
      "options": {
        "count": 20
      },
      "title": "Feed status by network",
      "type": "splunk.table"
    },
    "viz_typical_table": {
      "dataSources": {
        "primary": "ds_typical"
      },
      "options": {
        "count": 20
      },
      "title": "Published typical outdoor background (uSv/h)",
      "type": "splunk.table"
    },
    "viz_stations": {
      "dataSources": {
        "primary": "ds_stations"
      },
      "options": {
        "count": 20
      },
      "title": "Highest live government stations",
      "type": "splunk.table"
    },
    "viz_map": {
      "dataSources": {
        "primary": "ds_map"
      },
      "options": {
        "center": [
          35,
          10
        ],
        "zoom": 1.6,
        "layers": [
          {
            "type": "marker",
            "latitude": "> primary | seriesByName('lat')",
            "longitude": "> primary | seriesByName('lon')",
            "dataColors": "> primary | seriesByName('usvh') | rangeValue(markerColors)",
            "additionalTooltipFields": [
              "station_name",
              "country",
              "usvh",
              "source_network"
            ]
          }
        ]
      },
      "context": {
        "markerColors": [
          {
            "to": 0.1,
            "value": "#1a9850"
          },
          {
            "from": 0.1,
            "to": 0.2,
            "value": "#fdae61"
          },
          {
            "from": 0.2,
            "to": 1,
            "value": "#d73027"
          },
          {
            "from": 1,
            "value": "#7b3294"
          }
        ]
      },
      "title": "Live government stations (uSv/h: green <0.1, orange 0.1-0.2, red 0.2-1, purple >1)",
      "type": "splunk.map"
    },
    "viz_compare_status": {
      "dataSources": {
        "primary": "ds_compare_status"
      },
      "options": {},
      "title": "Comparison",
      "type": "splunk.singlevalue"
    },
    "viz_live_countries": {
      "dataSources": {
        "primary": "ds_live_country_count"
      },
      "options": {},
      "title": "Countries reporting live",
      "type": "splunk.singlevalue"
    },
    "viz_country_table": {
      "dataSources": {
        "primary": "ds_country_table"
      },
      "options": {
        "count": 20
      },
      "title": "Live radiation by country vs home",
      "type": "splunk.table"
    }
  },
  "dataSources": {
    "ds_home_line": {
      "name": "Home CPM and uSv/h",
      "options": {
        "query": "index=radsensor sourcetype!=gov:radiation:json\n| timechart span=10m avg(cpm) as CPM avg(usvh) as uSv_h"
      },
      "type": "ds.search"
    },
    "ds_home_cpm": {
      "name": "Home average CPM",
      "options": {
        "query": "index=radsensor sourcetype!=gov:radiation:json\n| timechart avg(cpm)"
      },
      "type": "ds.search"
    },
    "ds_home_usvh": {
      "name": "Home average uSv/h",
      "options": {
        "query": "index=radsensor sourcetype!=gov:radiation:json\n| timechart avg(usvh)"
      },
      "type": "ds.search"
    },
    "ds_home_latest_cpm": {
      "name": "Home latest CPM",
      "options": {
        "query": "index=radsensor sourcetype!=gov:radiation:json\n| stats latest(cpm) as cpm"
      },
      "type": "ds.search"
    },
    "ds_home_latest_usvh": {
      "name": "Home latest uSv/h",
      "options": {
        "query": "index=radsensor sourcetype!=gov:radiation:json\n| stats latest(usvh) as usvh"
      },
      "type": "ds.search"
    },
    "ds_typical": {
      "name": "Typical published background",
      "options": {
        "query": "| inputlookup typical_background.csv\n| table region network agency typical_usvh range_low_usvh range_high_usvh dose_component citation"
      },
      "type": "ds.search"
    },
    "ds_world_median": {
      "name": "World live median (median of country medians)",
      "options": {
        "query": "index=radsensor sourcetype=gov:radiation:json event_type=station usvh=*\n| stats latest(usvh) as usvh latest(_time) as last_time by country station_id\n| stats median(usvh) as usvh by country\n| stats median(usvh) as world_usvh\n| eval world_usvh=round(world_usvh, 4)"
      },
      "type": "ds.search"
    },
    "ds_live_country_count": {
      "name": "Countries with live data",
      "options": {
        "query": "index=radsensor sourcetype=gov:radiation:json event_type=station usvh=*\n| stats latest(usvh) as usvh latest(_time) as last_time by country station_id\n| stats dc(country) as countries"
      },
      "type": "ds.search"
    },
    "ds_home_vs_world": {
      "name": "Home minus world",
      "options": {
        "query": "index=radsensor sourcetype!=gov:radiation:json usvh=*\n| stats latest(usvh) as home_usvh\n| appendcols [\n  search index=radsensor sourcetype=gov:radiation:json event_type=station usvh=*\n  | stats latest(usvh) as usvh latest(_time) as last_time by country station_id\n  | stats median(usvh) as usvh by country\n  | stats median(usvh) as world_usvh\n]\n| eval delta_usvh=round(home_usvh-world_usvh, 4)\n| fields delta_usvh"
      },
      "type": "ds.search"
    },
    "ds_home_vs_world_ratio": {
      "name": "Home over world",
      "options": {
        "query": "index=radsensor sourcetype!=gov:radiation:json usvh=*\n| stats latest(usvh) as home_usvh\n| appendcols [\n  search index=radsensor sourcetype=gov:radiation:json event_type=station usvh=*\n  | stats latest(usvh) as usvh latest(_time) as last_time by country station_id\n  | stats median(usvh) as usvh by country\n  | stats median(usvh) as world_usvh\n]\n| eval ratio=round(home_usvh/world_usvh, 2)\n| fields ratio"
      },
      "type": "ds.search"
    },
    "ds_compare_status": {
      "name": "Comparison status",
      "options": {
        "query": "index=radsensor sourcetype!=gov:radiation:json usvh=*\n| stats latest(usvh) as home_usvh\n| appendcols [\n  search index=radsensor sourcetype=gov:radiation:json event_type=station usvh=*\n  | stats latest(usvh) as usvh latest(_time) as last_time by country station_id\n  | stats median(usvh) as usvh by country\n  | stats median(usvh) as world_usvh\n]\n| eval comparison=case(\n  isnull(world_usvh), \"Waiting for government feeds\",\n  isnull(home_usvh), \"Waiting for home sensor\",\n  home_usvh > world_usvh*1.5, \"Home is higher than the live world median\",\n  home_usvh < world_usvh*0.67, \"Home is lower than the live world median\",\n  1=1, \"Home is similar to the live world median\")\n| fields comparison"
      },
      "type": "ds.search"
    },
    "ds_compare_bar": {
      "name": "Home vs country medians",
      "options": {
        "query": "index=radsensor sourcetype!=gov:radiation:json usvh=*\n| stats latest(usvh) as usvh\n| eval country=\"Home sensor\"\n| append [\n  search index=radsensor sourcetype=gov:radiation:json event_type=station usvh=*\n  | stats latest(usvh) as usvh latest(_time) as last_time by country station_id\n  | stats median(usvh) as usvh by country\n]\n| eval usvh=round(usvh, 4)\n| sort usvh\n| fields country usvh"
      },
      "type": "ds.search"
    },
    "ds_compare_time": {
      "name": "Home vs countries over time",
      "options": {
        "query": "index=radsensor ((sourcetype!=gov:radiation:json usvh=*) OR (sourcetype=gov:radiation:json event_type=network_summary station_count>0))\n| eval series=if(sourcetype==\"gov:radiation:json\", country, \"Home sensor\")\n| eval usvh_plot=if(sourcetype==\"gov:radiation:json\", median_usvh, usvh)\n| timechart span=1h limit=20 avg(usvh_plot) by series"
      },
      "type": "ds.search"
    },
    "ds_country_table": {
      "name": "Live radiation by country vs home",
      "options": {
        "query": "index=radsensor sourcetype=gov:radiation:json event_type=station usvh=*\n| stats latest(usvh) as usvh latest(source_network) as source_network latest(dose_component) as dose_component latest(_time) as last_time by country station_id\n| stats count as stations median(usvh) as median_usvh min(usvh) as min_usvh max(usvh) as max_usvh max(last_time) as last_time first(source_network) as source_network first(dose_component) as dose_component by country\n| append [\n  | inputlookup typical_background.csv\n  | where region!=\"World\"\n  | rename region as country\n  | fields country typical_usvh\n]\n| stats first(*) as * by country\n| eval join_key=1\n| join type=left join_key [\n  search index=radsensor sourcetype!=gov:radiation:json usvh=*\n  | stats latest(usvh) as home_usvh\n  | eval join_key=1\n]\n| eval home_minus_country=round(home_usvh-median_usvh, 4)\n| eval home_ratio=round(home_usvh/median_usvh, 2)\n| eval comparison=case(\n  isnull(median_usvh), \"No live data in time range (typical \".typical_usvh.\")\",\n  isnull(home_usvh), \"Waiting for home sensor\",\n  home_usvh > median_usvh*1.5, \"Home higher\",\n  home_usvh < median_usvh*0.67, \"Home lower\",\n  1=1, \"Similar to home\")\n| eval live=if(isnull(median_usvh), 0, 1)\n| eval last_reading=strftime(last_time, \"%Y-%m-%d %H:%M\")\n| foreach median_usvh min_usvh max_usvh [ eval <<FIELD>>=round('<<FIELD>>', 4) ]\n| sort -live +country\n| table country source_network dose_component stations median_usvh min_usvh max_usvh typical_usvh home_usvh home_minus_country home_ratio comparison last_reading"
      },
      "type": "ds.search"
    },
    "ds_network_table": {
      "name": "Network summary table",
      "options": {
        "query": "index=radsensor sourcetype=gov:radiation:json event_type IN (network_summary, source_error)\n| stats latest(event_type) as last_event latest(error) as last_error latest(median_usvh) as median_usvh latest(station_count) as station_count latest(stale_dropped) as stale_dropped latest(country) as country latest(dose_component) as dose_component latest(_time) as last_time by source_network\n| eval status=if(last_event==\"source_error\", \"Error: \".last_error, \"OK\")\n| eval last_poll=strftime(last_time, \"%Y-%m-%d %H:%M\")\n| table source_network country dose_component status station_count stale_dropped median_usvh last_poll\n| sort source_network"
      },
      "type": "ds.search"
    },
    "ds_stations": {
      "name": "Highest stations",
      "options": {
        "query": "index=radsensor sourcetype=gov:radiation:json event_type=station usvh=*\n| stats latest(usvh) as usvh latest(station_name) as station_name latest(source_network) as source_network latest(dose_component) as dose_component latest(_time) as last_time by country station_id\n| sort - usvh\n| head 50\n| eval usvh=round(usvh, 4), measured=strftime(last_time, \"%Y-%m-%d %H:%M\")\n| table measured country source_network station_name usvh dose_component"
      },
      "type": "ds.search"
    },
    "ds_map": {
      "name": "Station map",
      "options": {
        "query": "index=radsensor sourcetype=gov:radiation:json event_type=station usvh=* lat=* lon=*\n| stats latest(usvh) as usvh latest(lat) as lat latest(lon) as lon latest(station_name) as station_name latest(source_network) as source_network by country station_id\n| eval usvh=round(usvh, 4)\n| table lat lon usvh station_name country source_network"
      },
      "type": "ds.search"
    }
  },
  "layout": {
    "globalInputs": [
      "input_global_trp"
    ],
    "layoutDefinitions": {
      "layout_home": {
        "options": {
          "height": 1080,
          "width": 1440
        },
        "structure": [
          {
            "item": "viz_home_md",
            "position": {
              "h": 88,
              "w": 1440,
              "x": 0,
              "y": 0
            },
            "type": "block"
          },
          {
            "item": "viz_home_line",
            "position": {
              "h": 400,
              "w": 1440,
              "x": 0,
              "y": 88
            },
            "type": "block"
          },
          {
            "item": "viz_home_cpm",
            "position": {
              "h": 280,
              "w": 360,
              "x": 0,
              "y": 488
            },
            "type": "block"
          },
          {
            "item": "viz_home_usvh",
            "position": {
              "h": 280,
              "w": 360,
              "x": 360,
              "y": 488
            },
            "type": "block"
          },
          {
            "item": "viz_home_latest_cpm",
            "position": {
              "h": 280,
              "w": 360,
              "x": 720,
              "y": 488
            },
            "type": "block"
          },
          {
            "item": "viz_home_latest_usvh",
            "position": {
              "h": 280,
              "w": 360,
              "x": 1080,
              "y": 488
            },
            "type": "block"
          }
        ],
        "type": "grid"
      },
      "layout_world": {
        "options": {
          "height": 2380,
          "width": 1440
        },
        "structure": [
          {
            "item": "viz_world_md",
            "position": {
              "h": 110,
              "w": 1440,
              "x": 0,
              "y": 0
            },
            "type": "block"
          },
          {
            "item": "viz_world_home",
            "position": {
              "h": 180,
              "w": 240,
              "x": 0,
              "y": 110
            },
            "type": "block"
          },
          {
            "item": "viz_world_median",
            "position": {
              "h": 180,
              "w": 240,
              "x": 240,
              "y": 110
            },
            "type": "block"
          },
          {
            "item": "viz_world_delta",
            "position": {
              "h": 180,
              "w": 240,
              "x": 480,
              "y": 110
            },
            "type": "block"
          },
          {
            "item": "viz_world_ratio",
            "position": {
              "h": 180,
              "w": 240,
              "x": 720,
              "y": 110
            },
            "type": "block"
          },
          {
            "item": "viz_live_countries",
            "position": {
              "h": 180,
              "w": 240,
              "x": 960,
              "y": 110
            },
            "type": "block"
          },
          {
            "item": "viz_compare_status",
            "position": {
              "h": 180,
              "w": 240,
              "x": 1200,
              "y": 110
            },
            "type": "block"
          },
          {
            "item": "viz_map",
            "position": {
              "h": 560,
              "w": 1440,
              "x": 0,
              "y": 290
            },
            "type": "block"
          },
          {
            "item": "viz_country_table",
            "position": {
              "h": 420,
              "w": 1440,
              "x": 0,
              "y": 850
            },
            "type": "block"
          },
          {
            "item": "viz_world_bar",
            "position": {
              "h": 380,
              "w": 720,
              "x": 0,
              "y": 1270
            },
            "type": "block"
          },
          {
            "item": "viz_world_line",
            "position": {
              "h": 380,
              "w": 720,
              "x": 720,
              "y": 1270
            },
            "type": "block"
          },
          {
            "item": "viz_stations",
            "position": {
              "h": 400,
              "w": 720,
              "x": 0,
              "y": 1650
            },
            "type": "block"
          },
          {
            "item": "viz_world_table",
            "position": {
              "h": 400,
              "w": 720,
              "x": 720,
              "y": 1650
            },
            "type": "block"
          },
          {
            "item": "viz_typical_table",
            "position": {
              "h": 320,
              "w": 1440,
              "x": 0,
              "y": 2050
            },
            "type": "block"
          }
        ],
        "type": "grid"
      }
    },
    "options": {},
    "tabs": {
      "items": [
        {
          "label": "Home sensor",
          "layoutId": "layout_home"
        },
        {
          "label": "Live world vs home",
          "layoutId": "layout_world"
        }
      ]
    }
  },
  "applicationProperties": {
    "hideEdit": false,
    "hideExport": false,
    "hideOpenInSearch": false
  }
}
